DROP VIEW "vritti_core"."inventory_levels";--> statement-breakpoint
ALTER TABLE "vritti_core"."storage_location_configs" RENAME TO "inventory_item_locations";--> statement-breakpoint
ALTER INDEX "vritti_core"."idx_storage_location_configs_item" RENAME TO "idx_inventory_item_locations_item";--> statement-breakpoint
ALTER INDEX "vritti_core"."idx_storage_location_configs_location" RENAME TO "idx_inventory_item_locations_location";--> statement-breakpoint
ALTER TABLE "vritti_core"."inventory_item_locations" RENAME CONSTRAINT "uq_storage_location_configs" TO "uq_inventory_item_locations";--> statement-breakpoint
CREATE VIEW "vritti_core"."inventory_levels" AS (select "vritti_core"."inventory_item_quants"."inventory_item_id", "vritti_core"."inventory_item_quants"."location_id", CAST(SUM("vritti_core"."inventory_item_quants"."quantity") AS TEXT) as "stocked_quantity", CAST(SUM("vritti_core"."inventory_item_quants"."reserved_quantity") AS TEXT) as "reserved_quantity", CAST(SUM("vritti_core"."inventory_item_quants"."quantity" - "vritti_core"."inventory_item_quants"."reserved_quantity") AS TEXT) as "available_quantity", "vritti_core"."inventory_item_locations"."reorder_level" from "vritti_core"."inventory_item_quants" left join "vritti_core"."inventory_item_locations" on "vritti_core"."inventory_item_quants"."inventory_item_id" = "vritti_core"."inventory_item_locations"."inventory_item_id" AND "vritti_core"."inventory_item_quants"."location_id" = "vritti_core"."inventory_item_locations"."location_id" group by "vritti_core"."inventory_item_quants"."inventory_item_id", "vritti_core"."inventory_item_quants"."location_id", "vritti_core"."inventory_item_locations"."reorder_level");